def handle_errors(func, *args, **kwargs):
    try:
        return func(*args, **kwargs)
    except Exception as e:
        print(f'Handled error: {type(e).__name__}')
        return None

def open_file(path):
    return handle_errors(lambda: open(path, 'r').read(), path)

def parse_json(text):
    return handle_errors(lambda: json.loads(text), text)

def connect_db(url):
    return handle_errors(lambda: sqlite3.connect(url), url)

